package com.valor.auth;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="customer_profiles") public class CustomerProfile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @OneToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false,unique=true) User user; @Column(name="full_name",nullable=false,length=160) String fullName; @Column(name="alternate_phone",length=20) String alternatePhone; @Column(name="company_name",length=200) String companyName; @Column(length=500) String address; @Column(name="has_lift") Boolean hasLift; @Column(name="referral_code",length=32,unique=true) String referralCode; @Column(precision=3,scale=2) java.math.BigDecimal rating; @Column(length=20,nullable=false) String status="ACTIVE"; @Column(name="is_active",nullable=false) boolean active=true; @Column(name="created_at",nullable=false) LocalDateTime createdAt; @Column(name="updated_at",nullable=false) LocalDateTime updatedAt; @PrePersist void p(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public User getUser(){return user;} public void setUser(User u){user=u;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public boolean isActive(){return active;} public String getStatus(){return status;} public Boolean getHasLift(){return hasLift;} public void setHasLift(Boolean v){hasLift=v;} public String getReferralCode(){return referralCode;} public void setReferralCode(String v){referralCode=v;}}
